Tìm tần số của giá trị $11$.

\choice
{  $10$  }
   { $9$   }
     { \True $8$  }
    { $7$   }
}{
\begin{tikzpicture}[y=0.3cm,x=0.8cm]
        %\draw[color=gray!50,line width=1.5pt]  (-1,-2.4)--(14.6,-2.4)--(14.6,6.5)--(-1,6.5)--cycle ;
        \foreach \i  in {2,4,...,10} 
        {
            \draw (0,\i) node[left]{$\i$};
            \draw (-0.1,\i)--(0.1,\i) ;
            \draw[gray!40] (0.5,\i)--(11.5,\i);
        }

        \foreach \x/\y/\z in {2/5/8,4/9/6,6/11/8,8/13/3,10/15/8} 
        {
            \draw ({\x},0) node[below]{$\y$};
            \draw ({\x},{\z}) node[above]{$\z$};
        }
        \draw [->] (0,0)--(11.5,0) node[below right]{Số từ mới};
        \draw [->] (0,0)--(0,11) node[above]{\text{Số ngày}};
        \draw [pattern=north east lines]  (1.6,0)--(1.6,8)--(2.4,8)--(2.4,0)--cycle   
        (3.6,0)--(3.6,6)--(4.4,6)--(4.4,0)--cycle  
        (5.6,0)--(5.6,8)--(6.4,8)--(6.4,0)--cycle   
         (7.6,0)--(7.6,3)--(8.4,3)--(8.4,0)--cycle   
         (9.6,0)--(9.6,8)--(10.4,8)--(10.4,0)--cycle   ;
        %[pattern=north east lines]
    \end{tikzpicture}
}
\loigiai{
Quan sát biểu đồ cột, đối chiếu cột có nhãn ngang tương ứng với giá trị đề bài hỏi rồi đọc số liệu trên đỉnh cột (hoặc trục đứng), ta được: Tần số của giá trị $11$ là: $8$.
}\end{ex}

